import json, re

with open('batches/batch_0068.json', encoding='utf-8') as f:
    data = json.load(f)

def try_fix(s):
    if not s:
        return s, "none"
    # count japanese-looking chars already
    def jp_ratio(t):
        if not t: return 0
        jp = sum(1 for c in t if '぀' <= c <= 'ヿ' or '一' <= c <= '鿿')
        return jp / max(1,len(t))
    best = (jp_ratio(s), s, "orig")
    candidates = []
    # utf8 bytes misread as latin1
    try:
        candidates.append((s.encode('latin1').decode('utf-8'), "latin1->utf8"))
    except Exception:
        pass
    # sjis misread as latin1
    try:
        candidates.append((s.encode('latin1').decode('cp932'), "latin1->cp932"))
    except Exception:
        pass
    # utf8 misread as cp932 (double mojibake other direction)
    try:
        candidates.append((s.encode('cp932').decode('utf-8'), "cp932->utf8"))
    except Exception:
        pass
    for cand, label in candidates:
        r = jp_ratio(cand)
        if r > best[0]:
            best = (r, cand, label)
    return best[1], best[2]

problem_idxs = []
results = {}
for item in data:
    idx = item['idx']
    out = {}
    changed = False
    for key in ['title','desc','body']:
        val = item.get(key,'')
        fixed, label = try_fix(val)
        out[key] = (fixed, label)
        if label != 'orig' and label != 'none':
            changed = True
    if changed:
        problem_idxs.append(idx)
        results[idx] = out

print("Fixed count:", len(problem_idxs))
print(problem_idxs)
